#!/usr/bin/env node
/* Build a single self-contained HTML by inlining the catalog script.
 *
 * The sheet normally loads the catalog from an external <script src>. iOS Safari
 * won't reliably load a sibling file when the HTML is opened from the Files app,
 * so this produces one standalone .html with the catalog embedded.
 *
 * Usage:
 *   node tools/build-bundle.mjs                       # embeds fad-catalog.local.js -> *.bundled.html
 *   node tools/build-bundle.mjs fad-catalog.js        # embeds the public catalog instead
 *   node tools/build-bundle.mjs <catalog.js> <out.html>
 *
 * WARNING: the default (local) catalog may contain copyrighted rulebook text.
 * Bundled output is gitignored (*.bundled.html) — keep it local, do not redistribute.
 */
import fs from 'node:fs';
import path from 'node:path';

const HTML = 'force-and-destiny-character-sheet.html';
const catalogPath = process.argv[2] || 'fad-catalog.local.js';
const outPath = process.argv[3] || 'force-and-destiny-character-sheet.bundled.html';

if(!fs.existsSync(HTML)){ console.error(`Not found: ${HTML} (run from the repo root)`); process.exit(1); }
if(!fs.existsSync(catalogPath)){ console.error(`Not found: ${catalogPath}`); process.exit(1); }

let html = fs.readFileSync(HTML, 'utf8');
const catalog = fs.readFileSync(catalogPath, 'utf8');

// Escape any "</script" inside the catalog so it can't close the inline <script>.
const safeCatalog = catalog.replace(/<\/(script)/gi, '<\\/$1');
const embed = `<script>/* Embedded catalog: ${path.basename(catalogPath)} — personal, non-redistributable build. Generated by tools/build-bundle.mjs */\n${safeCatalog}\n</script>`;

// Drop the optional local-override external tag (whichever catalog we pick is inlined once).
html = html.replace(/[ \t]*<script src="fad-catalog\.local\.js"><\/script>[^\n]*\n/, '');

// Replace the public external tag with the inline embed.
const before = html;
html = html.replace(/<script src="fad-catalog\.js"><\/script>/, embed);
if(html === before){ console.error('Could not find <script src="fad-catalog.js"></script> to replace.'); process.exit(1); }

fs.writeFileSync(outPath, html);
const kb = n => (n/1024).toFixed(0)+' KB';
console.log(`Wrote ${outPath} (${kb(Buffer.byteLength(html))}) with ${path.basename(catalogPath)} (${kb(Buffer.byteLength(catalog))}) embedded.`);
